<?php declare(strict_types=1);namespace App\Core;final class Crypto{public const ALPHABET='0123456789ABCDEFGHJKMNPQRSTVWXYZ';public static function generateKeypair():array{$b=sodium_crypto_sign_keypair();return['private'=>base64_encode(sodium_crypto_sign_secretkey($b)),'public'=>base64_encode(sodium_crypto_sign_publickey($b))];}public static function publicFromPrivate(string $y):string{$j=base64_decode(trim($y),true);if($j===false||strlen($j)!==SODIUM_CRYPTO_SIGN_SECRETKEYBYTES){throw new \InvalidArgumentException('Clé privée invalide (64 octets base64 attendus)');}return base64_encode(sodium_crypto_sign_publickey_from_secretkey($j));}public static function privateKey():string{$d=(string)Config::get('license.private_key_file',TP_ROOT.'/config/license_private.key');if(!is_file($d)){throw new \RuntimeException('Clé privée de licence absente : '.$d);}$C=trim((string)file_get_contents($d));$M=base64_decode($C,true);if($M===false||strlen($M)!==SODIUM_CRYPTO_SIGN_SECRETKEYBYTES){throw new \RuntimeException('Clé privée de licence corrompue');}return $M;}public static function publicKeyB64():string{$b=(string)Config::get('license.public_key_file',TP_ROOT.'/config/license_public.key');if(is_file($b)){return trim((string)file_get_contents($b));}return base64_encode(sodium_crypto_sign_publickey_from_secretkey(self::privateKey()));}public static function sign(string $w):string{return sodium_crypto_sign_detached($w,self::privateKey());}public static function verify(string $e,string $W,?string $w=null):bool{$g=base64_decode($w??self::publicKeyB64(),true);if($g===false||strlen($g)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES||strlen($W)!==SODIUM_CRYPTO_SIGN_BYTES){return false;}return sodium_crypto_sign_verify_detached($W,$e,$g);}public static function b64url(string $a):string{return rtrim(strtr(base64_encode($a),'+/','-_'),'=');}public static function b64urlDecode(string $E):string|false{return base64_decode(strtr($E,'-_','+/').str_repeat('=',(4-strlen($E)%4)%4),true);}public static function signedToken(array $z):string{$j=json_encode($z,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);return self::b64url($j).'.'.self::b64url(self::sign($j));}public static function verifyToken(string $X,?string $f=null):?array{$t=explode('.',$X);if(count($t)!==2){return null;}$d=self::b64urlDecode($t[0]);$P=self::b64urlDecode($t[1]);if($d===false||$P===false||!self::verify($d,$P,$f)){return null;}$Q=json_decode($d,true);return is_array($Q)?$Q:null;}public static function generateLicenseKey():string{$n='';for($d=0;$d<19;$d++){$n.=self::ALPHABET[random_int(0,31)];}$n.=self::checksumChar($n);return'TP1-'.implode('-',str_split($n,5));}public static function checksumChar(string $J):string{$K=0;foreach(str_split($J)as $O){$K+=strpos(self::ALPHABET,$O);}return self::ALPHABET[$K%32];}public static function normalizeLicenseKey(string $d):?string{$d=strtoupper(trim($d));$d=str_replace(['O','I','L'],['0','1','1'],$d);$Z=preg_replace('/[^0-9A-Z]/','',$d)??'';if(!str_starts_with($Z,'TP1')){return null;}$Q=substr($Z,3);if(strlen($Q)!==20||preg_match('/^['.self::ALPHABET.']{20}$/',$Q)!==1){return null;}if(self::checksumChar(substr($Q,0,19))!==$Q[19]){return null;}return'TP1-'.implode('-',str_split($Q,5));}public static function isValidLicenseKey(string $b):bool{return self::normalizeLicenseKey($b)!==null;}public static function randomToken(int $q=32):string{return bin2hex(random_bytes($q));}public static function hashToken(string $A):string{return hash('sha256',$A);}public static function hashPassword(string $o):string{return password_hash($o,PASSWORD_ARGON2ID,['memory_cost'=>65536,'time_cost'=>4,'threads'=>1]);}public static function verifyPassword(string $e,string $Y):bool{return password_verify($e,$Y);}public static function encrypt(string $q):string{$h=self::_g0xzi();$b=random_bytes(SODIUM_CRYPTO_AEAD_XCHACHA20POLY1305_IETF_NPUBBYTES);return base64_encode($b.sodium_crypto_aead_xchacha20poly1305_ietf_encrypt($q,'',$b,$h));}public static function decrypt(string $S):?string{$n=base